class SecurityValidationMiddleware(BaseHTTPMiddleware):
    """Validate MCP tool calls to prevent prompt injection and unauthorized access."""

    async def dispatch(self, request: Request, call_next):
        # Only validate MCP JSON-RPC tool calls (not health probes under /mcp/*)
        if request.url.path in ("/mcp/health", "/mcp/ready"):
            return await call_next(request)
        if not request.url.path.startswith("/mcp"):
            return await call_next(request)

        try:
            # Read and parse body
            body_bytes = await request.body()
            if not body_bytes:
                return await call_next(request)

            body = json.loads(body_bytes)
            method = body.get("method", "")

            # Log tools/list requests for monitoring (allowed but monitored)
            if method == "tools/list":
                client_ip = request.headers.get(
                    "X-Forwarded-For",
                    request.client.host if request.client else "unknown",
                )
                logging.info(f"tools/list called from IP: {repr(client_ip)}")

            # Validate tools/call requests
            if method == "tools/call":
                from data360.mcp_server.security_validator import (  # noqa: PLC0415
                    validate_search_arguments,
                    validate_tool_call,
                )

                params = body.get("params", {})
                tool_name = params.get("name", "")
                arguments = params.get("arguments", {})

                # Validate tool call
                is_valid, error_msg = validate_tool_call(tool_name, arguments)
                if not is_valid:
                    logging.warning(
                        f"Security violation: {repr(error_msg)} | Tool: {repr(tool_name)}"
                    )
                    return JSONResponse(
                        status_code=403,
                        content={
                            "jsonrpc": "2.0",
                            "id": jsonrpc_id(body.get("id")),
                            # `error_msg` embeds the offending tool name/parameter,
                            # so it is request-derived. Keep the html.escape() call
                            # at this sink: Veracode does not follow wrapper helpers.
                            "error": {
                                "code": -32001,
                                "message": html.escape(str(error_msg), quote=True),
                            },
                        },
                    )

                # Additional validation for all search term inputs
                if tool_name == "data360_search_indicators":
                    is_valid, error_msg = validate_search_arguments(arguments)
                    if not is_valid:
                        logging.warning(
                            "Search query blocked: %s",
                            repr(str(arguments)[:200]),
                        )
                        return JSONResponse(
                            status_code=403,
                            content={
                                "jsonrpc": "2.0",
                                "id": jsonrpc_id(body.get("id")),
                                "error": {
                                    "code": -32001,
                                    "message": html.escape(
                                        str(error_msg), quote=True
                                    ),
                                },
                            },
                        )

        except json.JSONDecodeError:
            pass  # Let MCP handle invalid JSON
        except Exception:
            logging.error("Security validation error", exc_info=True)
            # Continue on validation errors to avoid blocking legitimate requests

        return await call_next(request)


class AuditLogMiddleware(BaseHTTPMiddleware):
    """Log structured audit entries for every MCP request."""

    async def dispatch(self, request: Request, call_next):
        # Only audit MCP JSON-RPC calls (not health probes)
        if request.url.path in ("/mcp/health", "/mcp/ready"):
            return await call_next(request)
        if not request.url.path.startswith("/mcp"):
            return await call_next(request)
        session_id = str(uuid.uuid4())
        requestor_id = request.headers.get(
            "X-Forwarded-For", request.client.host if request.client else "unknown"
        )
        timestamp = datetime.now(UTC).isoformat()
        # Read and restore body so downstream handlers still receive it
        body_bytes = await request.body()
        prompt = ""
        prompt_hash = ""
        try:
            body = json.loads(body_bytes)
            method = body.get("method", "")
            params = body.get("params", {})
            prompt = json.dumps(
                {"method": method, "params": params}, separators=(",", ":")
            )
            prompt_hash = hashlib.sha256(prompt.encode()).hexdigest()[:16]
        except Exception:
            pass
        response = await call_next(request)

        # CWE-117: repr is the recognized cleanser for log forging and has to be
        # called at the log statement itself — a helper around it is not treated
        # as a cleanser, so each sink builds its dims inline rather than sharing
        # a pre-built dict.
        _audit_logger.info(
            "mcp_audit",
            extra={
                "custom_dimensions": {
                    "session_id": session_id,
                    "requestor_id": repr(requestor_id),
                    "timestamp": timestamp,
                    "prompt": repr(prompt),
                    "prompt_hash": prompt_hash,
                    "status_code": repr(response.status_code),
                    "path": repr(request.url.path),
                }
            },
        )

        # Also log as custom event for Splunk forwarding
        if _telemetry_client:
            _telemetry_client.info(
                "MCP_Request",
                extra={
                    "custom_dimensions": {
                        "session_id": session_id,
                        "requestor_id": repr(requestor_id),
                        "timestamp": timestamp,
                        "prompt": repr(prompt),
                        "prompt_hash": prompt_hash,
                        "status_code": repr(response.status_code),
                        "path": repr(request.url.path),
                    },
                    "event_name": "MCP_Request",
                },
            )

        return response


